(() => {
  'use strict';
  const $=s=>document.querySelector(s), app=window.patioAdmin;
  let site=null, editing=null, limit=60, loading=null;
  const pages={'index.html':'Inicio','carta.html':'Carta','celebraciones.html':'Celebraciones','galeria.html':'Galería','informacion.html':'Información','global':'Cabecera y pie de página'};
  const kinds={text:'Texto',image:'Imagen',link:'Enlace',video:'Vídeo'};
  function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
  function message(text,error=false){$('#website-status').textContent=text;$('#website-status').dataset.error=String(error);}
  $('#website-view').innerHTML='<p class="section-note">Elige una página y una sección, o pulsa en un texto o fotografía de la vista previa. Los cambios guardados se publican en la web.</p><div class="toolbar"><label>Página<select id="content-page"></select></label><label>Sección<select id="content-section"></select></label><label class="search-label">Buscar contenido<input id="content-search" type="search" placeholder="Título, texto o imagen"></label><button id="preview-toggle" class="quiet">Ver vista previa</button></div><p id="website-status" role="status"></p><iframe id="website-preview" title="Vista previa editable de la página" hidden></iframe><div id="content-fields" class="content-fields"></div><button id="content-more" class="quiet" hidden>Mostrar más</button>';
  $('#categories-view').innerHTML='<p class="section-note">Los nombres se actualizan en los filtros y apartados de la carta. Los platos conservan su categoría.</p><div id="category-editors"></div>';
  $('#schedule-view').innerHTML='<p class="section-note">Este horario aparece en la web y controla los días y servicios disponibles para reservar. Las reservas existentes no se cancelan automáticamente.</p><form id="schedule-form"><div id="schedule-days"></div><label>Cierres excepcionales<textarea id="schedule-exceptions" rows="4" placeholder="Una fecha por línea: 2026-12-25"></textarea><span class="optional">Formato AAAA-MM-DD. Se bloquearán aunque el día de la semana esté abierto.</span></label><p id="schedule-status" role="status"></p><button class="primary" type="submit">Guardar horario</button></form>';
  const dialog=el('dialog');dialog.id='content-dialog';dialog.innerHTML='<div class="dialog-heading"><h2 id="content-title">Editar contenido</h2><button type="button" class="quiet" id="content-close">Cerrar</button></div><form id="content-form" class="editor"><p id="content-location" class="section-note wide"></p><label class="wide" id="content-value-label">Contenido<textarea id="content-value" rows="5" maxlength="5000"></textarea></label><label class="wide" id="content-en-label">En inglés<textarea id="content-en" rows="5" maxlength="5000"></textarea></label><div id="content-image-editor" class="wide image-editor"><img id="content-preview" alt="Imagen seleccionada"><label>Cambiar imagen<input id="content-file" type="file" accept="image/jpeg,image/png,image/webp"></label></div><label id="content-alt-label" class="wide">Descripción de la imagen<input id="content-alt" maxlength="240"></label><p id="content-edit-status" class="wide" role="status"></p><div class="editor-actions wide"><button type="button" id="content-reset" class="quiet">Restaurar original</button><button type="submit" class="primary">Guardar y publicar</button></div></form>';document.body.append(dialog);dialog.setAttribute('aria-labelledby','content-title');
  for(const [value,label] of Object.entries(pages)){const o=el('option',label);o.value=value;$('#content-page').append(o);}
  async function load(force=false){if(site&&!force)return site;if(loading)return loading;loading=app.api('website').then(data=>{site=data;sections();renderFields();renderCategories();renderSchedule();return data;}).finally(()=>{loading=null;});return loading;}
  function sections(){const select=$('#content-section'),old=select.value;select.replaceChildren();const all=el('option','Todas las secciones');all.value='';select.append(all);for(const name of [...new Set(site.fields.filter(f=>f.page===$('#content-page').value).map(f=>f.section))]){const o=el('option',name);o.value=name;select.append(o);}if([...select.options].some(o=>o.value===old))select.value=old;}
  const current=field=>{const saved=site.content[field.id];return saved&&!saved.reset?{...field,...saved}:field;};
  function renderFields(){if(!site)return;const q=$('#content-search').value.toLocaleLowerCase(),section=$('#content-section').value;const fields=site.fields.filter(f=>f.page===$('#content-page').value&&(!section||f.section===section)&&(f.section+' '+current(f).value+' '+(f.label||'')).toLocaleLowerCase().includes(q));const list=$('#content-fields');list.replaceChildren();for(const field of fields.slice(0,limit)){const row=el('article',undefined,'content-row');const value=current(field);if(field.type==='image'){const image=el('img');image.src=value.value;image.alt=value.alt||'';image.loading='lazy';row.append(image);}const copy=el('div');copy.append(el('p',field.section,'product-meta'),el('h3',field.type==='image'?(field.id==='site-logo'?'Logotipo':value.alt||'Fotografía'):field.label||value.value),el('span',kinds[field.type]+(site.content[field.id]&&!site.content[field.id].reset?' · Personalizado':''),'product-meta'));const button=el('button','Editar','quiet');button.type='button';button.addEventListener('click',()=>edit(field));row.append(copy,button);list.append(row);}if(!fields.length)list.append(el('p','No hay contenido con estos filtros.'));$('#content-more').hidden=fields.length<=limit;}
  function edit(field){editing=field;const value=current(field);$('#content-form').reset();$('#content-title').textContent='Editar '+kinds[field.type].toLowerCase();$('#content-location').textContent=pages[field.page]+' · '+field.section;$('#content-value').value=value.value;$('#content-en').value=value.en||value.value;$('#content-value-label').hidden=field.type==='image';$('#content-en-label').hidden=field.type!=='text';$('#content-image-editor').hidden=field.type!=='image';$('#content-alt-label').hidden=field.type!=='image';$('#content-preview').src=field.type==='image'?value.value:'';$('#content-alt').value=value.alt||'';$('#content-edit-status').textContent=field.type==='video'?'Enlace HTTPS directo a un archivo MP4. La portada se cambia desde su campo de imagen.':'';dialog.showModal();}
  async function saveContent(reset=false){const button=$('#content-form [type="submit"]');button.disabled=true;$('#content-reset').disabled=true;$('#content-edit-status').textContent='Guardando…';try{let value=$('#content-value').value;if(!reset&&editing.type==='image')value=$('#content-file').files[0]?await app.upload($('#content-file').files[0]):current(editing).value;const result=await app.api('content','PUT',{id:editing.id,version:site.content[editing.id]?.version||0,reset,value,en:$('#content-en').value,alt:$('#content-alt').value});site.content[editing.id]=result.result;dialog.close();renderFields();refreshPreview();message(reset?'Contenido original restaurado.':'Cambio publicado.');}catch(error){$('#content-edit-status').textContent=error.message;}finally{button.disabled=false;$('#content-reset').disabled=false;}}
  $('#content-form').addEventListener('submit',e=>{e.preventDefault();saveContent();});$('#content-reset').addEventListener('click',()=>saveContent(true));$('#content-close').addEventListener('click',()=>dialog.close());
  $('#content-file').addEventListener('change',()=>{const file=$('#content-file').files[0];if(!file)return;const url=URL.createObjectURL(file);$('#content-preview').src=url;$('#content-preview').onload=()=>URL.revokeObjectURL(url);});
  function refreshPreview(){if(!$('#website-preview').hidden){const page=$('#content-page').value;$('#website-preview').src=(page==='global'?'index.html':page)+'?editor=1&updated='+Date.now();}}
  $('#preview-toggle').addEventListener('click',()=>{$('#website-preview').hidden=!$('#website-preview').hidden;$('#preview-toggle').textContent=$('#website-preview').hidden?'Ver vista previa':'Ocultar vista previa';refreshPreview();});
  window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==$('#website-preview').contentWindow||event.data?.type!=='patio-edit'||!site)return;const field=site.fields.find(f=>f.id===event.data.id);if(field)edit(field);});
  $('#content-page').addEventListener('change',()=>{limit=60;sections();renderFields();refreshPreview();});for(const id of ['content-section','content-search'])$('#'+id).addEventListener('input',()=>{limit=60;renderFields();});$('#content-more').addEventListener('click',()=>{limit+=60;renderFields();});
  function renderCategories(){const list=$('#category-editors');list.replaceChildren();for(const category of site.categories){const form=el('form',undefined,'category-editor');const es=el('input'),en=el('input');es.value=category.es;en.value=category.en;es.required=true;es.maxLength=en.maxLength=100;const label=el('label','Nombre de la categoría'),english=el('label','En inglés'),button=el('button','Guardar categoría','primary'),status=el('p');status.setAttribute('role','status');label.append(es);english.append(en);form.append(label,english,button,status);form.addEventListener('submit',async e=>{e.preventDefault();button.disabled=true;try{const result=await app.api('category','PUT',{id:category.id,version:category.version||1,es:es.value,en:en.value});Object.assign(category,result.result);await app.load();status.textContent='Categoría publicada.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});list.append(form);}}
  function renderSchedule(){const names=['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];const list=$('#schedule-days');list.replaceChildren();for(const day of [1,2,3,4,5,6,0]){const row=site.schedule.days.find(d=>d.day===day);const block=el('fieldset',undefined,'schedule-day');block.dataset.day=day;block.append(el('legend',names[day]));const closed=el('input');closed.type='checkbox';closed.name='closed';closed.checked=row.closed;const label=el('label','Cerrado');label.className='closed-toggle';label.prepend(closed);block.append(label);for(const service of ['comida','cena']){const slot=row.slots.find(s=>s.service===service),group=el('div',undefined,'schedule-slot');group.append(el('span',service==='comida'?'Comida':'Cena'));for(const key of ['start','end']){const input=el('input');input.type='time';input.name=service+'-'+key;input.value=slot?.[key]||'';input.setAttribute('aria-label',names[day]+' · '+service+' · '+(key==='start'?'Apertura':'Cierre'));group.append(input);}block.append(group);}list.append(block);}$('#schedule-exceptions').value=site.schedule.closedDates.join('\n');}
  $('#schedule-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('[type="submit"]');button.disabled=true;try{const days=[...document.querySelectorAll('.schedule-day')].map(block=>({day:Number(block.dataset.day),closed:block.querySelector('[name="closed"]').checked,slots:['comida','cena'].map(service=>({service,start:block.querySelector('[name="'+service+'-start"]').value,end:block.querySelector('[name="'+service+'-end"]').value})).filter(s=>s.start||s.end)}));const closedDates=$('#schedule-exceptions').value.split(/[\s,]+/).filter(Boolean);const result=await app.api('schedule','PUT',{version:site.schedule.version,days,closedDates});site.schedule=result.result;$('#schedule-status').textContent='Horario publicado. El calendario de reservas ya utiliza estos días y servicios.';}catch(error){$('#schedule-status').textContent=error.message;}finally{button.disabled=false;}});
  window.addEventListener('adminview',async event=>{if(['website','categories','schedule'].includes(event.detail))try{await load();}catch(error){message(error.message,true);$('#workspace-status').textContent=error.message;}});
  $('#refresh').addEventListener('click',()=>{if(site)load(true).catch(e=>message(e.message,true));});
  window.addEventListener('adminclosed',()=>{site=null;editing=null;dialog.close();$('#website-preview').src='about:blank';$('#content-fields').replaceChildren();$('#category-editors').replaceChildren();$('#schedule-days').replaceChildren();});
})();
